// Real Unitree A2 manufacturer-material pilot: existing Factory, PREVIEW ONLY.
// Exact PR HEAD is generated by CI at _site/a2-factory-preview.html.
// No public SKU, CRM submission or browser-side form posts.
const { test, expect } = require('@playwright/test');
const ORIGIN='http://127.0.0.1:4173';

for (const width of [1440,390,360]) {
  test('Unitree A2 real Factory official preview ' + width + 'px', async ({ page }) => {
    const failures=[];
    page.on('pageerror', err=>failures.push(String(err)));
    await page.setViewportSize({width,height:900});
    const reply=await page.goto(ORIGIN+'/a2-factory-preview.html', {waitUntil:'networkidle'});
    expect(reply.status()).toBe(200);
    await expect(page.locator('main[data-product-id="unitree-a2"]')).toHaveCount(1);
    await expect(page.locator('main[data-product-family="quadruped"]')).toHaveCount(1);
    await expect(page.locator('main h1')).toHaveText('Unitree A2');
    await expect(page.locator('meta[name="robots"]')).toHaveAttribute('content','noindex,nofollow');
    // P0 design contract: preview must use the existing ONE shared logo/menu,
    // not the old hard-coded text-only Factory Header.
    await expect(page.locator('header.site-header[data-shared-layout="header"]')).toHaveCount(1);
    const brand=page.locator('header.site-header a.brand[href="/index.html"]');
    await expect(brand).toHaveCount(1);
    await expect(page.locator('header .brand-logo-pc')).toHaveCount(1);
    await expect(page.locator('header .brand-logo-sp')).toHaveCount(1);
    await expect(page.locator('header nav#nav[aria-label="グローバルナビゲーション"]')).toHaveCount(1);
    await expect(page.locator('header nav#nav a[href="/contact.html"]')).toHaveCount(1);
    const footer=page.locator('footer.footer[data-shared-layout="footer"]');
    await expect(footer).toHaveCount(1);
    await expect(footer.locator('img.aa8-main-logo')).toHaveCount(1);
    expect(await footer.locator('img.aa8-main-logo').evaluate(el=>el.complete&&el.naturalWidth>0)).toBe(true);
    await expect(footer.locator('nav.footer-links a[href="/contact.html"]')).toHaveCount(1);
    await expect(footer.locator('nav.footer-utility-links a[href="/products.html"]')).toHaveCount(1);
    expect(await footer.innerText()).toContain('© AirAdmin8 Inc. All rights reserved.');
    const footerLogo=footer.locator('img.aa8-main-logo');
    await expect(footerLogo).toHaveAttribute('src',/airadmin8-robotics-logo-footer\.svg/);
    if(width<=390){
      const columns=await footer.locator('nav.footer-links').evaluate(el=>
        getComputedStyle(el).gridTemplateColumns.split(/\s+/).filter(Boolean));
      expect(columns).toHaveLength(2);
    }
    expect(await page.locator('script[data-aa8-menu-runtime="true"]').count()).toBe(1);
    expect(await page.locator('script[src*="analytics-events.js"],script[src*="site.js"]').count()).toBe(0);
    if(width<=390){
      const menu=page.locator('header button.menu[aria-controls="nav"]');
      await expect(menu).toBeVisible();
      await expect(menu).toHaveAttribute('aria-expanded','false');
      await menu.click();
      await expect(menu).toHaveAttribute('aria-expanded','true');
      await expect(page.locator('header nav#nav a[href="/products.html"]')).toBeVisible();
      await page.locator('header nav#nav a[href="/products.html"]').focus();
      await page.keyboard.press('Escape');
      await expect(menu).toHaveAttribute('aria-expanded','false');
      await expect(menu).toBeFocused();
      await menu.click();
      await expect(menu).toHaveAttribute('aria-expanded','true');
      await page.locator('header nav#nav a[href="/products.html"]').evaluate(el=>{
        el.addEventListener('click',e=>e.preventDefault(),{once:true});
        el.click();
      });
      await expect(menu).toHaveAttribute('aria-expanded','false');
      // All chapter links remain reachable by horizontal swipe AND keyboard.
      const nav=page.locator('.g1-anchor-nav .g1-shell');
      const last=nav.locator('a[href="#contact-product"]');
      const before=await nav.evaluate(el=>({width:el.clientWidth,scrollWidth:el.scrollWidth}));
      expect(before.scrollWidth).toBeGreaterThan(before.width);
      await last.focus();
      await expect(last).toBeInViewport();
      expect(await nav.evaluate(el=>el.scrollLeft)).toBeGreaterThan(0);
    }else{
      await expect(page.locator('header nav#nav a[href="/products.html"]')).toBeVisible();
    }
    const text=await page.locator('main').innerText();
    expect(text).toContain('A2-PRO');
    expect(text).toContain('LiDAR ×1＋HDカメラ ×1');
    expect(text).toContain('LiDAR ×2＋HDカメラ ×1');
    expect(text).toContain('25 kg');
    expect(text).toContain('100 kg');
    // Real manufacturer table: 10 mechanical + 15 electrical + 9 performance
    // + 3 other = 37 parameter rows for TWO named models, not 37 per model.
    const specs=page.locator('#specifications');
    await expect(page.locator('#model-selection')).toBeVisible();
    await expect(specs.locator('tr.a2-category-row')).toHaveCount(4);
    await expect(specs.locator('tr.a2-spec-row[data-spec-row="true"]')).toHaveCount(37);
    await expect(specs.locator('td[data-model="A2"]')).toHaveCount(37);
    await expect(specs.locator('td[data-model="A2-PRO"]')).toHaveCount(37);
    for(const group of ['機械パラメータ','電気特性','性能パラメータ','その他']){
      await expect(specs.locator('tr.a2-category-row').filter({hasText:group})).toHaveCount(1);
    }
    await expect(specs.locator('td[data-model="A2"]').filter({hasText:'IP56'})).toHaveCount(1);
    await expect(specs.locator('td[data-model="A2-PRO"]').filter({hasText:'IP56～IP67'})).toHaveCount(1);
    // Model choice must survive the existing contact CTA, not silently default to A2.
    const a2Consult=page.locator('[data-model-inquiry="A2"]');
    const proConsult=page.locator('[data-model-inquiry="A2-PRO"]');
    await expect(a2Consult).toHaveCount(1);
    await expect(proConsult).toHaveCount(1);
    for(const [link,model] of [[a2Consult,'Unitree A2'],[proConsult,'Unitree A2-PRO']]){
      const href=new URL(await link.getAttribute('href'),ORIGIN);
      expect(href.searchParams.get('product')).toBe(model);
      expect(href.searchParams.get('maker')).toBe('Unitree');
      expect(href.searchParams.get('service')).toBe('industrial-poc');
      expect(href.searchParams.get('source_page')).toBe('https://robotics.air-admin8.co.jp/products/unitree-a2.html');
    }
    const hero=page.locator('.g1-hero-image img');
    await expect(hero).toBeVisible();
    expect(await hero.evaluate(el=>el.complete && el.naturalWidth>100)).toBe(true);
    const makerPhotos=page.locator('main img[src*="a2-factory-pilot/unitree-a2-maker-"]');
    expect(await makerPhotos.count()).toBeGreaterThanOrEqual(5);
    for(let i=0;i<5;i++){
      const img=makerPhotos.nth(i);
      await img.scrollIntoViewIfNeeded();
      await expect.poll(async()=>img.evaluate(el=>el.complete && el.naturalWidth>100)).toBe(true);
    }
    const cta=page.locator('a[data-factory-cta="hero"][href*="/contact.html"]');
    await expect(cta).toBeVisible();
    const url=new URL(await cta.getAttribute('href'),ORIGIN);
    expect(url.searchParams.get('product')).toBe('Unitree A2');
    expect(url.searchParams.get('maker')).toBe('Unitree');
    expect(url.searchParams.get('service')).toBe('industrial-poc');
    expect(url.searchParams.get('source_page')).toBe('https://robotics.air-admin8.co.jp/products/unitree-a2.html');
    expect(failures).toEqual([]);
    expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width+2);
    // Do not click submit or write actual customer inquiries.
  });
}

/* CEO full-page screenshot: readability and A2-only layout acceptance.
 * This is a real-browser CSS check, not a replacement for maker facts QA. */
for (const width of [1440, 390, 360]) {
  test('A2 visual acceptance: model choices, sources, CTA and no clipped text '+width, async ({ page }) => {
    await page.setViewportSize({ width, height: 900 });
    const response=await page.goto(ORIGIN+'/a2-factory-preview.html', { waitUntil:'networkidle' });
    expect(response.status()).toBe(200);
    const root=page.locator('main[data-product-id="unitree-a2"]');
    await expect(root).toBeVisible();
    const models=page.locator('#model-selection .g1-factory-spec-table tr');
    await expect(models).toHaveCount(2);
    for (const tr of await models.all()) {
      await expect(tr).toBeVisible();
      const btn=tr.locator('[data-model-inquiry]');
      await expect(btn).toBeVisible();
      const style=await btn.evaluate(el=>({color:getComputedStyle(el).color,display:getComputedStyle(el).display}));
      expect(style.color).toBe('rgb(255, 255, 255)');
      expect(style.display).not.toBe('none');
    }
    await expect(page.locator('#development .g1-fine')).toBeVisible();
    await expect(page.locator('#solutions .g1-fine')).toBeVisible();
    await expect(page.locator('#introduction .g1-fine')).toBeVisible();
    await expect(page.locator('#contact-product .g1-cta-card')).toHaveCount(3);
    await expect(page.locator('#contact-product > .g1-shell > p:not(.g1-kicker)').first()).toBeVisible();
    for (const item of await page.locator('#development article,#solutions article,#introduction article').all()) {
      expect(await item.evaluate(el=>el.getBoundingClientRect().width)).toBeGreaterThan(100);
    }
    const cards=await models.evaluateAll(els=>els.map(el=>({
      width:el.getBoundingClientRect().width,
      scrollWidth:el.scrollWidth,
      left:el.getBoundingClientRect().left,
      right:el.getBoundingClientRect().right,
    })));
    expect(cards.every(c=>c.scrollWidth<=c.width+2)).toBe(true);

    // Visual acceptance: real rendered photos MUST display after lazy scroll.
    // An asset SHA alone is not a visual acceptance.
    const everyImage=page.locator('main img');
    for (const image of await everyImage.all()) {
      await image.scrollIntoViewIfNeeded();
      await expect.poll(
        async()=>image.evaluate(el=>el.complete && el.naturalWidth>0),
        {timeout:10000}
      ).toBe(true);
    }
    expect(await everyImage.count()).toBeGreaterThanOrEqual(12);
    await expect(page.locator('#specifications .g1-factory-source')).toBeVisible();
    const heroHeight=await page.locator('main > .g1-hero').evaluate(el=>el.getBoundingClientRect().height);
    if(width===1440) {
      expect(heroHeight).toBeLessThan(610);
      const grid=await page.locator('#introduction .g1-factory-applications').evaluate(el=>
        getComputedStyle(el).gridTemplateColumns.split(/\s+/).filter(Boolean).length);
      expect(grid).toBe(3);
    }
    const fs=require('node:fs');
    fs.mkdirSync('a2-qa-artifacts',{recursive:true});
    await page.screenshot({
      path:'a2-qa-artifacts/a2-fullpage-'+width+'.png',
      fullPage:true,
      animations:'disabled'
    });

    if (width<=390) {
      expect(cards[0].right).toBeLessThanOrEqual(width+2);
      expect(cards[1].left).toBeGreaterThanOrEqual(-2);
      expect(await models.nth(0).evaluate(el=>getComputedStyle(el.parentElement).gridTemplateColumns.split(' ').filter(Boolean).length)).toBe(1);
    } else {
      expect(cards[0].right).toBeLessThan(cards[1].left);
    }
  });
}

// Independent computed-style gate: TechShare-inspired white/gray specification
// table is mandatory for A2 PC/SP, not merely present in committed CSS.
// All 37 rows and both 37-cell model columns remain required.
for (const width of [1440,390,360]) {
  test('A2 neutral white-gray specs actual computed style '+width, async ({page}) => {
    await page.setViewportSize({width,height:900});
    const resp=await page.goto(ORIGIN+'/a2-factory-preview.html',{waitUntil:'networkidle'});
    expect(resp.status()).toBe(200);
    const spec=page.locator('main[data-product-id="unitree-a2"] #specifications');
    const rows=spec.locator('tr.a2-spec-row[data-spec-row="true"]');
    await expect(rows).toHaveCount(37);
    await expect(spec.locator('tr.a2-category-row')).toHaveCount(4);
    await expect(spec.locator('td[data-model="A2"]')).toHaveCount(37);
    await expect(spec.locator('td[data-model="A2-PRO"]')).toHaveCount(37);
    const backgrounds=await rows.evaluateAll(els=>els.slice(0,6).map(el=>getComputedStyle(el).backgroundColor));
    expect(backgrounds).toEqual([
      'rgb(255, 255, 255)','rgb(245, 245, 245)',
      'rgb(255, 255, 255)','rgb(245, 245, 245)',
      'rgb(255, 255, 255)','rgb(245, 245, 245)',
    ]);
    const cat=await spec.locator('tr.a2-category-row th').first()
      .evaluate(el=>({bg:getComputedStyle(el).backgroundColor,
                      color:getComputedStyle(el).color}));
    expect(cat.bg).toBe('rgb(238, 238, 238)');
    expect(cat.color).toBe('rgb(36, 36, 36)');
    const cells=await rows.first().locator('th,td').evaluateAll(els=>els.map(el=>({
      fg:getComputedStyle(el).color,
      border:getComputedStyle(el).borderBottomColor,
      font:parseFloat(getComputedStyle(el).fontSize),
    })));
    expect(cells).toHaveLength(3);
    expect(cells.every(x=>x.fg==='rgb(36, 36, 36)' && x.font>=14)).toBe(true);
    expect(cells.some(x=>x.border==='rgb(217, 217, 217)')).toBe(true);
    const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+2);
    expect(overflow).toBe(false);
    // Avoid assertions on TechShare's R&D variant weight: data source/reviewer
    // gate is independent and must stay HOLD until true factual approval.
  });
}


// Reference image fidelity: colors alone are NOT enough.
// TechShare-style PC spec cells are center-aligned; mobile keeps accessible
// labeled two-model blocks with intact text, not a shrunk desktop table.
for (const width of [1440,390,360]) {
  test('A2 screenshot reference visual alignment '+width, async ({page}) => {
    await page.setViewportSize({width,height:900});
    const reply=await page.goto(ORIGIN+'/a2-factory-preview.html',{waitUntil:'networkidle'});
    expect(reply.status()).toBe(200);
    const area=page.locator('main[data-product-id="unitree-a2"] #specifications');
    await expect(area.locator('.a2-spec-row')).toHaveCount(37);
    const computed=await area.evaluate(el=>{
      const r=el.querySelector('.a2-spec-row');
      const group=el.querySelector('.a2-category-row th');
      const title=el.querySelector('.g1-shell > h2');
      const th=r.querySelector('th'), td=r.querySelector('td');
      return {
        rowBg:getComputedStyle(r).backgroundColor,
        keyAlign:getComputedStyle(th).textAlign,
        valueAlign:getComputedStyle(td).textAlign,
        groupBg:getComputedStyle(group).backgroundColor,
        groupAlign:getComputedStyle(group).textAlign,
        titleBorder:getComputedStyle(title).borderBottomColor,
        valueBorder:getComputedStyle(td).borderBottomColor,
        widths:[th,td].map(x=>x.getBoundingClientRect().width),
      };
    });
    expect(computed.rowBg).toBe('rgb(255, 255, 255)');
    expect(computed.groupBg).toBe('rgb(238, 238, 238)');
    expect(computed.valueBorder).toBe('rgb(217, 217, 217)');
    if(width===1440){
      expect(computed.keyAlign).toBe('center');
      expect(computed.valueAlign).toBe('center');
      expect(computed.groupAlign).toBe('center');
      expect(computed.widths[0]).toBeGreaterThan(200);
    }else{
      expect(computed.keyAlign).toBe('left');
      expect(computed.valueAlign).toBe('left');
    }
    // Immutable independent artifact: compact focused screenshot, not only a
    // screen-height table partially hidden by the sticky site navigation.
    const fs=require('node:fs');
    fs.mkdirSync('a2-qa-artifacts',{recursive:true});
    await area.locator('.g1-shell > h2').screenshot({path:'a2-qa-artifacts/a2-spec-heading-'+width+'.png'});
    const rows=area.locator('tr.a2-spec-row');
    await rows.first().scrollIntoViewIfNeeded();
    await rows.first().screenshot({path:'a2-qa-artifacts/a2-spec-first-row-'+width+'.png'});
    expect(await page.evaluate(()=>document.documentElement.scrollWidth))
      .toBeLessThanOrEqual(width+2);
  });
}

// Independent customer-facing Gate for the reported full-page P1s.
// Must inspect computed styles and real anchor offset, not just source CSS.
for (const width of [1440,390,360]) {
  test('A2 customer CTA and readability regression '+width,async({page})=>{
    await page.setViewportSize({width,height:900});
    await page.emulateMedia({reducedMotion:'reduce'});
    const resp=await page.goto(ORIGIN+'/a2-factory-preview.html',{waitUntil:'networkidle'});
    expect(resp.status()).toBe(200);
    const root=page.locator('main[data-product-id="unitree-a2"]');
    const consultation=root.locator('#contact-product .g1-cta-card[data-factory-cta="3"]');
    await expect(consultation).toHaveCount(1);
    const details=await consultation.evaluate(el=>({
      border:getComputedStyle(el).borderTopColor,
      borderWidth:parseFloat(getComputedStyle(el).borderTopWidth),
      titleFont:parseFloat(getComputedStyle(el.querySelector('strong')).fontSize),
      bodyFont:parseFloat(getComputedStyle(el.querySelector('small')).fontSize),
      href:el.getAttribute('href')
    }));
    expect(details.border).toBe('rgb(0, 125, 169)');
    expect(details.borderWidth).toBeGreaterThanOrEqual(2);
    expect(details.titleFont).toBeGreaterThanOrEqual(18);
    expect(details.bodyFont).toBeGreaterThanOrEqual(14);
    const target=new URL(details.href,ORIGIN);
    expect(target.pathname).toBe('/contact.html');
    expect(target.searchParams.get('product')).toBe('Unitree A2');
    expect(target.searchParams.get('maker')).toBe('Unitree');
    const caution=root.locator('#development .g1-fine');
    await expect(caution).toBeVisible();
    expect(await caution.evaluate(el=>parseFloat(getComputedStyle(el).fontSize))).toBeGreaterThanOrEqual(14);
    const related=root.locator('#related .g1-factory-related-card small').first();
    expect(await related.evaluate(el=>parseFloat(getComputedStyle(el).fontSize))).toBeGreaterThanOrEqual(14);
    await page.evaluate(()=>document.getElementById('contact-product')
      .scrollIntoView({block:'start',behavior:'instant'}));
    const pos=await page.evaluate(()=>{
      const nav=document.querySelector('.g1-anchor-nav').getBoundingClientRect();
      const section=document.getElementById('contact-product');
      const title=section.querySelector('h2').getBoundingClientRect();
      const button=section.querySelector('[data-factory-cta="3"]').getBoundingClientRect();
      return {navBottom:nav.bottom,titleTop:title.top,buttonBottom:button.bottom};
    });
    // The colored SECTION background may extend behind a sticky nav;
    // text and the actual consultation action must remain unobscured.
    expect(pos.titleTop).toBeGreaterThanOrEqual(pos.navBottom+6);
    expect(pos.buttonBottom).toBeGreaterThan(pos.navBottom+44);
    expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width+2);
    const fs=require('node:fs');
    fs.mkdirSync('a2-qa-artifacts',{recursive:true});
    await consultation.screenshot({path:'a2-qa-artifacts/a2-consult-'+width+'.png'});
  });
}
